// Diff against the last status seen per work order; emit an event only on change.
const seen = $getWorkflowStaticData('global');
seen.status ??= {};
const names = Object.fromEntries(Object.entries(JSON.parse($env.RENTVINE_STATUS_IDS ?? '{}')).map(([name, id]) => [String(id), name]));
const out = [];
for (const { json } of $input.all()) {
  const rows = Array.isArray(json) ? json : json.data ?? json.workOrders ?? [];
  for (const row of rows) {
    const wo = row.workOrder ?? row;
    const id = String(wo.workOrderID ?? wo.id);
    const statusId = String(wo.primaryWorkOrderStatusID ?? wo.workOrderStatusID ?? '');
    const before = seen.status[id];
    seen.status[id] = statusId;
    if (before === undefined || before === statusId) continue; // first sight = baseline; same = no change
    const payload = { id: `${id}-${statusId}-${wo.dateTimeModified ?? ''}`, event: 'workorder.updated', source: 'rentvine', workOrderId: id, status: names[statusId] ?? statusId, occurredAt: wo.dateTimeModified ?? new Date().toISOString() };
    out.push({ json: { payload: JSON.stringify(payload) } });
  }
}
return out;
